const fixTime=(v:string)=>{const m=/^(\d{1,2}):?(\d{2})?$/.exec(v);if(!m)return v;const h=+m[1],n=+(m[2]||0);return h>24||n>59||(h===24&&n>0)?v:String(h).padStart(2,'0')+':'+String(n).padStart(2,'0')};
function Cell({type,value,onChange}:{type:string;value:any;onChange:(v:string)=>void}){return type==='time24'?<Input type="text" inputMode="numeric" placeholder="hh:mm" maxLength={5} value={value??''} onChange={e=>{let v=e.target.value.replace(/[^\d:]/g,'');if(/^\d{4}$/.test(v))v=v.slice(0,2)+':'+v.slice(2);onChange(v)}} onBlur={e=>{const v=fixTime(e.target.value);if(v!==e.target.value)onChange(v)}}/>:type==='number'?<Input type="text" inputMode="decimal" value={String(value??'').replace('.',',')} onChange={e=>{const v=e.target.value.replace(',','.');if(/^\d*\.?\d*$/.test(v))onChange(v)}}/>:<Input type={type} value={value??''} onChange={e=>onChange(e.target.value)}/>}
function ExpandedEmployeeReport({data,active}:{data:Data;active:boolean}){const allEmployees=data.resources.filter(r=>r.kind==='employee');const restricted=data.me?.accessRole!=='planer';const employees=restricted?allEmployees.filter(e=>e.id===data.me?.resourceId):allEmployees;const [employeeId,setEmployeeId]=useState('');useEffect(()=>{if(restricted&&data.me?.resourceId)setEmployeeId(data.me.resourceId)},[restricted,data.me?.resourceId]);const [month,setMonth]=useState(()=>format(new Date(),'yyyy-MM'));const todayCardRef=useRef<HTMLDetailsElement|null>(null);useEffect(()=>{if(!active||!employeeId)return;const t=setTimeout(()=>todayCardRef.current?.scrollIntoView({block:'start',behavior:'smooth'}),50);return()=>clearTimeout(t)},[active,employeeId]);const [rows,setRows]=useState<Record<string,any>>({});const timers=useRef<Record<string,ReturnType<typeof setTimeout>>>({});const employee=employees.find(r=>r.id===employeeId);const first=new Date(month+'-01T00:00:00');const days=Array.from({length:new Date(first.getFullYear(),first.getMonth()+1,0).getDate()},(_,i)=>addDays(first,i));const base=(d:string)=>{const i=dayInfo(data.assignments,data.punches,employeeId,d);const site=i.type==='vacation'?'Urlaub':i.type==='unpaid'?'Unbezahlter Urlaub':i.type==='sick'?'Krank':data.projects.find(x=>x.id===i.projectId)?.name||'';return{...i,site,kmOut:'',kmBack:'',notes:''}};const row=(d:string)=>{const e:Record<string,any>={...entryOf(data,employeeId,d),...(rows[employeeId+'|'+d]||{})},m:Record<string,any>={...base(d),...e};if((e.travelStart||e.travelEnd)&&!e.absence&&!['vacation','unpaid','sick'].includes(m.type)){const a=mins(m.travelStart),z=mins(m.travelEnd);if(!isNaN(a)&&!isNaN(z)){let x=z-a;if(x<0)x+=1440;m.absence=(x/60).toFixed(2)}}return m};const setRow=(d:string,k:string,v:string)=>{const key=employeeId+'|'+d,rid=employeeId,next={...entryOf(data,rid,d),...(rows[key]||{}),[k]:v};setRows(x=>({...x,[key]:next}));clearTimeout(timers.current[key]);timers.current[key]=setTimeout(()=>{fetch('/api/data',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'dayEntry',resourceId:rid,day:d,data:Object.fromEntries(Object.entries(next).filter(([,x])=>x!==''))})}).then(r=>{if(!r.ok)throw Error()}).catch(()=>toast.error('Eintrag konnte nicht gespeichert werden.'))},600)};const absenceType=(d:string)=>data.assignments.find(x=>x.resource_id===employeeId&&x.day===d)?.assignment_type||'';const isMissing=(d:string)=>{if(d>=iso(new Date()))return false;if(['vacation','unpaid','sick'].includes(absenceType(d)))return false;return !Number(row(d).workHours)};const [periodMode,setPeriodMode]=useState<'week'|'month'>('week');const [weekAnchor,setWeekAnchor]=useState(()=>startOfWeek(new Date(),{weekStartsOn:1}));const weekDays=Array.from({length:7},(_,i)=>addDays(weekAnchor,i));const meal=(d:string)=>{const m=row(d).meal;return m!==undefined&&m!==''&&!isNaN(Number(m))?Number(m):mealFor(absenceType(d),Number(row(d).absence||0))};const absent=(d:string)=>['vacation','unpaid','sick'].includes(absenceType(d));const mealLabel=(d:string)=>['vacation','unpaid','sick'].includes(absenceType(d))?'–':`${meal(d)} €`;const total=(k:string)=>days.reduce((n,d)=>n+Number(row(iso(d))[k]||0),0);const absenceDates=(type:string)=>{const selected=days.filter(d=>data.assignments.some(x=>x.resource_id===employeeId&&x.day===iso(d)&&x.assignment_type===type));if(!selected.length)return 'keine';const ranges:string[]=[];let start=selected[0],prev=selected[0];for(const d of selected.slice(1)){if((d.getTime()-prev.getTime())/86400000===1){prev=d}else{ranges.push(start.getTime()===prev.getTime()?format(start,'dd.MM.'):`von ${format(start,'dd.MM.')} bis ${format(prev,'dd.MM.')}`);start=prev=d}}ranges.push(start.getTime()===prev.getTime()?format(start,'dd.MM.'):`von ${format(start,'dd.MM.')} bis ${format(prev,'dd.MM.')}`);return ranges.join(', ')};const absenceCount=(type:string)=>days.filter(d=>{const a=data.assignments.find(x=>x.resource_id===employeeId&&x.day===iso(d));return a?.assignment_type===type}).length;async function print(){const [{jsPDF},{default:autoTable}]=await Promise.all([import('jspdf'),import('jspdf-autotable')]);const doc=new jsPDF({orientation:'landscape',unit:'mm',format:'a4'});const head=[['Datum','Tag','Reisebeginn','Reiseende','Baustelle / Reiseanlass','Abw. h','Verpfl.','Arbeit von','Arbeit bis','Pause','Arbeitszeit','Anfahrt','Km hin','Km zurück','Notiz']];const widths=[13,9,17,17,56,13,14,17,17,13,17,14,12,14,38];const body=(list:Date[])=>list.map(d=>{const r=row(iso(d));return [format(d,'dd.MM.'),format(d,'EEE',{locale:de}),r.travelStart,r.travelEnd,r.site,cm(r.absence),cm(mealLabel(iso(d))),r.workStart,r.workEnd,r.pause,cm(r.workHours),cm(r.travelHours),cm(r.kmOut),cm(r.kmBack),r.notes].map(v=>String(v??''))});const subtotal=(list:Date[],key:string)=>list.reduce((n,d)=>n+Number(row(iso(d))[key]||0),0);const mealSub=(list:Date[])=>list.reduce((n,d)=>n+meal(iso(d)),0);const nf=(n:number,d=2)=>n.toFixed(d).replace('.',',');const box=(x:number,y:number,w:number,h:number,label:string,value:string,big:boolean)=>{doc.setDrawColor(125,141,163);doc.setFillColor(234,240,247);doc.rect(x,y,w,h,big?'FD':'S');doc.setTextColor(59,74,96);doc.setFont('helvetica','normal');doc.setFontSize(8);doc.text(label,x+3,y+4.5);doc.setTextColor(23,35,58);doc.setFont('helvetica','bold');doc.setFontSize(big?14:10);doc.text(value,x+3,y+(big?11.5:9.5))};const kpis=(list:Date[],suffix:string,y:number)=>{const w=(281-3*4)/4;[['Reisekosten',nf(mealSub(list))+' €'],['Normalstunden',nf(subtotal(list,'workHours'))+' h'],['Anfahrtsstunden',nf(subtotal(list,'travelHours'))+' h'],['Kilometer',nf(subtotal(list,'kmOut')+subtotal(list,'kmBack'),0)+' km']].forEach(([l,v],i)=>box(8+i*(w+4),y,w,15,(l+' '+suffix).trim(),v,true))};const absences=(y:number)=>{const w=(281-2*4)/3;[['Urlaubstage','vacation'],['Unbezahlter Urlaub','unpaid'],['Krank','sick']].forEach(([l,t],i)=>box(8+i*(w+4),y,w,12,`${l}  ${absenceCount(t)}`,absenceDates(t),false))};const page=(list:Date[],sub:boolean)=>{doc.setTextColor(23,35,58);doc.setFont('helvetica','bold');doc.setFontSize(16);doc.text('Reisekostenabrechnung und Stundenabrechnung',8,14);doc.setFontSize(10);doc.text('Name:',8,20);doc.text('Monat/Jahr:',90,20);doc.setFont('helvetica','normal');doc.text(String(employee?.name??''),19,20);doc.text(format(first,'MM/yyyy'),113,20);autoTable(doc,{head,body:body(list),startY:24,margin:{left:8,right:8},theme:'grid',tableWidth:281,styles:{fontSize:7.5,cellPadding:1.2,lineColor:[125,141,163],lineWidth:0.2,textColor:[23,35,58],valign:'middle',minCellHeight:7},headStyles:{fillColor:[234,240,247],textColor:[23,35,58],fontStyle:'bold'},columnStyles:Object.fromEntries(widths.map((w,i)=>[i,{cellWidth:w}])),rowPageBreak:'avoid'});const y=(doc as any).lastAutoTable.finalY+4;if(sub){doc.setFont('helvetica','bold');doc.setFontSize(10);doc.text('Zwischensumme Blatt 1',8,y+3);kpis(list,'',y+6)}else{kpis(days,'gesamt',y);absences(y+19)}};page(days.slice(0,15),true);doc.addPage();page(days.slice(15),false);doc.save(`Stundenabrechnung ${String(employee?.name??'').replace(/[^\w\- ]+/g,'').trim()} ${format(first,'MM-yyyy')}.pdf`)}return <section className="panel employee-report"><div className="section-heading"><div><h2>Reisekosten- und Stundenabrechnung</h2><p>Monatliche, manuell editierbare Abrechnung.</p></div><Button variant="outline" disabled={!employeeId} onClick={print}>PDF herunterladen</Button></div><div className="report-controls"><Choice label="Mitarbeiter" value={employeeId} onChange={setEmployeeId} options={employees} disabled={restricted}/><Input type="month" value={month} onChange={e=>setMonth(e.target.value)}/></div>{employeeId&&<><div className="report-table wide desktop-table"><table><thead><tr><th>Datum</th><th>Tag</th><th>Reisebeginn</th><th>Reiseende</th><th>Baustelle</th><th>Abwesenheit h</th><th>Verpflegung</th><th>Arbeit von</th><th>Arbeit bis</th><th>Pause min</th><th>Arbeitszeit h</th><th>Anfahrt h</th><th>Km hin</th><th>Km zurück</th><th>Notiz</th></tr></thead><tbody>{days.map(d=>{const k=iso(d),r=row(k);return <tr key={k}><td>{format(d,'dd.MM.')}</td><td>{format(d,'EEE',{locale:de})}</td>{[['travelStart','time'],['travelEnd','time24'],['site','text'],['absence','number']].map(([key,type])=><td key={key}><Cell type={type} value={r[key]} onChange={v=>setRow(k,key,v)}/></td>)}<td>{absent(k)?mealLabel(k):<Cell type="number" value={r.meal??meal(k)} onChange={v=>setRow(k,'meal',v)}/>}</td>{[['workStart','time'],['workEnd','time'],['pause','number'],['workHours','number'],['travelHours','number'],['kmOut','number'],['kmBack','number'],['notes','text']].map(([key,type])=><td key={key}><Cell type={type} value={r[key]} onChange={v=>setRow(k,key,v)}/></td>)}</tr>})}</tbody></table></div><div className="expense-cards-toolbar"><div className="button-row"><Button type="button" variant={periodMode==='week'?undefined:'outline'} size="sm" onClick={()=>setPeriodMode('week')}>Diese Woche</Button><Button type="button" variant={periodMode==='month'?undefined:'outline'} size="sm" onClick={()=>setPeriodMode('month')}>Ganzer Monat</Button></div>{periodMode==='week'&&<div className="button-row"><Button type="button" variant="outline" size="icon" aria-label="Vorherige Woche" onClick={()=>setWeekAnchor(w=>addDays(w,-7))}><ChevronLeft/></Button><Button type="button" variant="outline" size="icon" aria-label="Nächste Woche" onClick={()=>setWeekAnchor(w=>addDays(w,7))}><ChevronRight/></Button></div>}</div><div className="expense-cards">{(periodMode==='week'?weekDays:days).map(d=>{const k=iso(d),r=row(k);const isToday=k===iso(new Date());const missing=isMissing(k);return <details className="expense-day-card" key={k} open={isToday||(periodMode==='week'&&missing)} ref={isToday?todayCardRef:undefined}><summary className="expense-day-head"><b>{format(d,'dd.MM.')}</b><span>{format(d,'EEEE',{locale:de})}</span>{missing&&<span className="missing-badge">Fehlt</span>}</summary><div className="expense-day-grid"><div className="ef ef-wide"><label>Baustelle / Reiseanlass</label><Input type="text" value={r.site} onChange={e=>setRow(k,'site',e.target.value)}/></div><div className="ef"><label>Abwesenheit h</label><Cell type="number" value={r.absence} onChange={v=>setRow(k,'absence',v)}/></div><div className="ef"><label>Verpflegung</label>{absent(k)?<span className="ef-readonly">{mealLabel(k)}</span>:<Cell type="number" value={r.meal??meal(k)} onChange={v=>setRow(k,'meal',v)}/>}</div>{[['workStart','Arbeit von','time'],['workEnd','Arbeit bis','time'],['pause','Pause min','number'],['workHours','Arbeitszeit h','number']].map(([key,label,type])=><div className="ef" key={key}><label>{label}</label><Cell type={type} value={r[key]} onChange={v=>setRow(k,key,v)}/></div>)}</div><details className="expense-secondary"><summary>Weitere Angaben</summary><div className="expense-day-grid">{[['travelStart','Reisebeginn','time'],['travelEnd','Reiseende','time24'],['travelHours','Anfahrt h','number'],['kmOut','Km hin','number'],['kmBack','Km zurück','number']].map(([key,label,type])=><div className="ef" key={key}><label>{label}</label><Cell type={type} value={r[key]} onChange={v=>setRow(k,key,v)}/></div>)}<div className="ef ef-wide"><label>Notiz</label><Input type="text" value={r.notes} onChange={e=>setRow(k,'notes',e.target.value)}/></div></div></details></details>})}</div><div className="report-total absence-summary"><span>Urlaub: {absenceCount('vacation')} Tage ({absenceDates('vacation')})</span><span>Unbezahlter Urlaub: {absenceCount('unpaid')} Tage ({absenceDates('unpaid')})</span><span>Krank: {absenceCount('sick')} Tage ({absenceDates('sick')})</span></div></>}</section>}
function Evaluation({data}:{data:Data}){const [month,setMonth]=useState(()=>format(new Date(),'yyyy-MM'));const first=new Date(month+'-01T00:00:00');const days=Array.from({length:new Date(first.getFullYear(),first.getMonth()+1,0).getDate()},(_,i)=>iso(addDays(first,i)));const rows=data.resources.filter(r=>r.kind==='employee').map(r=>{let work=0,travel=0,cost=0,km=0;for(const d of days){const b=dayInfo(data.assignments,data.punches,r.id,d),i:Record<string,any>={...b,...entryOf(data,r.id,d)};work+=Number(i.workHours||0);travel+=Number(i.travelHours||0);cost+=i.meal!==undefined&&i.meal!==''&&!isNaN(Number(i.meal))?Number(i.meal):mealFor(b.type,Number(i.absence||0));km+=Number(i.kmOut||0)+Number(i.kmBack||0)}return{r,work,travel,cost,km}});const sum=(k:'work'|'travel'|'cost'|'km')=>rows.reduce((n,x)=>n+x[k],0);return <section className="panel employee-report"><div className="section-heading"><div><h2>Stunden und Reisekosten je Mitarbeiter</h2><p>Aus Stempelzeiten und den gespeicherten Angaben der Spesenabrechnung. Urlaub, unbezahlter Urlaub und Krank zählen mit 8 Stunden.</p></div><Input type="month" value={month} onChange={e=>setMonth(e.target.value)}/></div><Table><TableHeader><TableRow><TableHead>Mitarbeiter</TableHead><TableHead className="text-right">Arbeitszeit h</TableHead><TableHead className="text-right">Anfahrtsstunden h</TableHead><TableHead className="text-right">Reisekosten</TableHead><TableHead className="text-right">Kilometer</TableHead></TableRow></TableHeader><TableBody>{rows.map(({r,work,travel,cost,km})=><TableRow key={r.id}><TableCell>{r.name}</TableCell><TableCell className="text-right">{work.toFixed(2)}</TableCell><TableCell className="text-right">{travel.toFixed(2)}</TableCell><TableCell className="text-right">{cost.toFixed(2)} €</TableCell><TableCell className="text-right">{km.toFixed(0)}</TableCell></TableRow>)}<TableRow><TableCell><b>Gesamt</b></TableCell><TableCell className="text-right"><b>{sum('work').toFixed(2)}</b></TableCell><TableCell className="text-right"><b>{sum('travel').toFixed(2)}</b></TableCell><TableCell className="text-right"><b>{sum('cost').toFixed(2)} €</b></TableCell><TableCell className="text-right"><b>{sum('km').toFixed(0)}</b></TableCell></TableRow></TableBody></Table></section>}
function Group({label,rows,days,data,today,assignForm,reorderResources,openProject,selectedIds,toggleSelection,dragDown,dragEnter,wasDragged,canManage}:{label:string;rows:Resource[];days:Date[];data:Data;today:string;assignForm:(r:Resource,day:string,a?:Assignment)=>void;reorderResources:(ids:string[])=>void;openProject:(projectId:string,assignment:Assignment)=>void;selectedIds:string[];toggleSelection:(id:string)=>void;dragDown:(id:string)=>void;dragEnter:(id:string)=>void;wasDragged:()=>boolean;canManage:boolean}){return <><tr className="group-row"><td colSpan={8}>{label}<span>{rows.length}</span></td></tr>{rows.map(r=><tr key={r.id} draggable={canManage} onDragStart={e=>e.dataTransfer.setData('resourceId',r.id)} onDragOver={e=>e.preventDefault()} onDrop={e=>{if(!canManage)return;e.preventDefault();const from=e.dataTransfer.getData('resourceId');if(!from||from===r.id)return;const ids=rows.map(x=>x.id);const a=ids.indexOf(from),b=ids.indexOf(r.id);if(a<0||b<0)return;ids.splice(a,1);ids.splice(b,0,from);reorderResources([...data.resources.filter(x=>x.kind!==r.kind).map(x=>x.id),...ids])}}><td className="person-col"><div className="person"><span className={`avatar ${r.kind==='contractor'?'contractor':''}`}>{r.kind==='employee'?initials(r.name):<Building2 size={18}/>}</span><div><b>{r.name}</b><small>{r.kind==='employee'?r.role:'Extern'}</small></div></div></td>{days.map((d,i)=>{const assignments=data.assignments.filter(a=>a.resource_id===r.id&&a.day===iso(d));return <td key={iso(d)} className={`${i>4?'weekend':''} ${iso(d)===today?'today-cell':''}`}><div className="day-slot">{assignments.map(a=>{const p=data.projects.find(p=>p.id===a.project_id);const statusLabel=a.assignment_type==='vacation'?'Urlaub':a.assignment_type==='unpaid'?'Unbezahlter Urlaub':a.assignment_type==='sick'?'Krank':a.assignment_type==='homeoffice'?'Homeoffice':p?.name||'Projekt';return <div key={a.id} className={`assignment-wrap ${selectedIds.includes(a.id)?'selected':''}`} onMouseDown={canManage?e=>{if(e.button===0&&!(e.target as HTMLElement).closest('input')){e.preventDefault();dragDown(a.id)}}:undefined} onMouseEnter={canManage?e=>{if(e.buttons===1)dragEnter(a.id)}:undefined}>{canManage&&<label className="assignment-select" title="Einteilung markieren"><input type="checkbox" checked={selectedIds.includes(a.id)} onChange={()=>toggleSelection(a.id)} aria-label={`${statusLabel} markieren`}/></label>}<button className="assignment" style={{borderColor:(p?.color||'#2865df')+'4d',background:(p?.color||'#2865df')+'14','--c':p?.color||'#2865df'} as any} onClick={()=>{if(wasDragged())return;if(a.project_id)openProject(a.project_id,a);else if(canManage)assignForm(r,iso(d),a)}}><b>{statusLabel}</b><span>{r.kind==='contractor'?<><Users size={12}/>{a.count} Monteure</>:'Eingeplant'}</span></button></div>})}{canManage&&<button className={`add-slot ${assignments.length?'additional':''}`} aria-label={`${r.name} am ${format(d,'dd.MM.yyyy')} einteilen`} onClick={()=>assignForm(r,iso(d))} disabled={false}><Plus size={15}/>{assignments.length?'Weiteres Projekt':''}</button>}</div></td>})}</tr>)}</>}
